darpan.datasource.DataSourceDefinition.definitionJson:
{
 "connection": {
  "urlTemplate": "{baseUrl}/rest/s1/graphql",
  "auth": {
   "kindField": "authType",
   "defaultKind": "NONE",
   "headersJsonField": "headersJson",
   "kinds": {
    "NONE": {
     "method": "NONE"
    },
    "BASIC": {
     "method": "BASIC",
     "userField": "username",
     "passwordField": "password"
    },
    "BEARER": {
     "method": "BEARER",
     "tokenFields": [
      "apiToken",
      "password"
     ]
    },
    "API_KEY": {
     "method": "HEADER",
     "header": "api_key",
     "tokenFields": [
      "apiToken",
      "password"
     ]
    }
   }
  },
  "timeoutSeconds": 120
 },
 "limits": {
  "maxCostPerCall": 1000,
  "maxInFlight": 6,
  "errorCodeAt": "errors[*].extensions.code",
  "throttledCodes": [
   "THROTTLED"
  ],
  "maxThrottleWaitSeconds": 300,
  "costRefusedCodes": [
   "COST_EXCEEDED"
  ],
  "retryStatuses": [
   429,
   502,
   503,
   504
  ],
  "maxAttempts": 3,
  "retryBackoffMillis": 2000,
  "costBucket": {
   "at": "extensions.cost.throttleStatus",
   "available": "currentlyAvailable",
   "maximum": "maximumAvailable",
   "restoreRate": "restoreRate"
  }
 },
 "batchRecords": 1000,
 "metadata": {
  "droppedNullLineIdCount": 0
 },
 "warnings": [
  {
   "count": "keptNullShopifyIdCount",
   "text": "{n} order item(s) had no Shopify order or line id; they were compared with it left empty."
  }
 ],
 "steps": [
  {
   "id": "orders",
   "kind": "query",
   "document": "query OmsOrderGrain($q: String, $first: Int, $after: String) {\n  orders(query: $q, sortKey: ORDER_DATE, reverse: false, first: $first, after: $after) {\n    edges { node {\n      orderId orderName externalId statusId orderTypeId orderDate grandTotal currencyUomId\n      paymentPreferences(first: 2) { paymentMethodTypeId statusId maxAmount }\n      shipGroups(first: 3) { edges { node { shipGroupSeqId facilityId shipmentMethodTypeId } } }\n      billToCustomer { firstName lastName }\n    } }\n    pageInfo { hasNextPage endCursor }\n  }\n}",
   "connectionAt": "orders",
   "recordsAt": "edges[*].node",
   "hasNextAt": "pageInfo.hasNextPage",
   "cursorAt": "pageInfo.endCursor",
   "bind": {
    "window": {
     "variables": {
      "q": "orderDate:>={from} orderDate:<{thru} orderTypeId:SALES_ORDER"
     },
     "field": "orderDate",
     "sliceHours": 24,
     "instantFormat": "ISO_INSTANT",
     "parallel": 4
    },
    "ids": {
     "variables": {
      "q": "{keyField}:{ids} orderTypeId:SALES_ORDER"
     },
     "from": "LOOKUP_KEYS",
     "chunk": 100,
     "parallel": 4,
     "defaultKeyField": "orderId",
     "keyFields": {
      "orderId": "orderId",
      "omsOrderId": "orderId",
      "externalId": "externalId"
     },
     "idPattern": "[A-Za-z0-9_\\-]{1,40}",
     "separator": ","
    }
   },
   "paging": {
    "firstVariable": "first",
    "afterVariable": "after",
    "pageSize": {
     "budget": 850,
     "costPerRecord": 32.2
    },
    "maxPages": 20000
   },
   "reservation": 988
  },
  {
   "id": "groupList",
   "kind": "unwrap",
   "of": "orders",
   "field": "shipGroups",
   "path": "edges[*].node"
  },
  {
   "id": "orderFacts",
   "kind": "derive",
   "on": "orders",
   "rules": [
    {
     "set": "orderDate",
     "value": {
      "fn": "epochMillis",
      "args": [
       {
        "copy": "orderDate"
       }
      ]
     }
    },
    {
     "set": "grandTotal",
     "value": {
      "fn": "decimal",
      "args": [
       {
        "copy": "grandTotal"
       }
      ]
     }
    }
   ]
  },
  {
   "id": "facilities",
   "kind": "query",
   "document": "query OmsFacilityNames($q: String, $first: Int, $after: String) {\n  facilities(query: $q, first: $first, after: $after) {\n    edges { node { facilityId facilityName } }\n    pageInfo { hasNextPage endCursor }\n  }\n}",
   "connectionAt": "facilities",
   "recordsAt": "edges[*].node",
   "hasNextAt": "pageInfo.hasNextPage",
   "cursorAt": "pageInfo.endCursor",
   "bind": {
    "ids": {
     "variables": {
      "q": "facilityId:{ids}"
     },
     "from": "orders.shipGroups[*].facilityId",
     "chunk": 100,
     "separator": ",",
     "parallel": 4
    }
   },
   "paging": {
    "firstVariable": "first",
    "afterVariable": "after",
    "pageSize": 100
   },
   "reservation": 350
  },
  {
   "id": "items",
   "kind": "query",
   "document": "query OmsUnitOrderItems($q: String, $first: Int, $after: String) {\n  orderItems(query: $q, first: $first, after: $after) {\n    edges { node { orderId orderItemSeqId externalId productId quantity statusId shipGroupSeqId } }\n    pageInfo { hasNextPage endCursor }\n  }\n}",
   "connectionAt": "orderItems",
   "recordsAt": "edges[*].node",
   "hasNextAt": "pageInfo.hasNextPage",
   "cursorAt": "pageInfo.endCursor",
   "bind": {
    "ids": {
     "variables": {
      "q": "orderId:{ids}"
     },
     "from": "orders.orderId",
     "chunk": 100,
     "separator": ",",
     "parallel": 4
    }
   },
   "paging": {
    "firstVariable": "first",
    "afterVariable": "after",
    "pageSize": 100
   },
   "reservation": 850
  },
  {
   "id": "products",
   "kind": "query",
   "document": "query OmsProductNames($q: String, $first: Int, $after: String) {\n  products(query: $q, first: $first, after: $after) {\n    edges { node { productId internalName } }\n    pageInfo { hasNextPage endCursor }\n  }\n}",
   "connectionAt": "products",
   "recordsAt": "edges[*].node",
   "hasNextAt": "pageInfo.hasNextPage",
   "cursorAt": "pageInfo.endCursor",
   "bind": {
    "ids": {
     "variables": {
      "q": "productId:{ids}"
     },
     "from": "items.productId",
     "chunk": 100,
     "separator": ",",
     "parallel": 4
    }
   },
   "paging": {
    "firstVariable": "first",
    "afterVariable": "after",
    "pageSize": 100
   },
   "reservation": 350
  },
  {
   "id": "itemSku",
   "kind": "join",
   "into": "items",
   "from": "products",
   "on": [
    {
     "into": "productId",
     "from": "productId"
    }
   ],
   "copy": {
    "sku": "internalName"
   }
  },
  {
   "id": "groupFacilityName",
   "kind": "join",
   "into": "orders",
   "from": "facilities",
   "at": "shipGroups[*]",
   "atOn": [
    {
     "at": "facilityId",
     "from": "facilityId"
    }
   ],
   "copy": {
    "facilityName": "facilityName"
   }
  },
  {
   "id": "itemsInGroups",
   "kind": "join",
   "into": "orders",
   "from": "items",
   "on": [
    {
     "into": "orderId",
     "from": "orderId"
    }
   ],
   "at": "shipGroups[*]",
   "atOn": [
    {
     "at": "shipGroupSeqId",
     "from": "shipGroupSeqId"
    }
   ],
   "many": true,
   "as": "items",
   "missingAt": {
    "create": true,
    "set": {
     "facilityId": null
    }
   }
  },
  {
   "id": "perItem",
   "kind": "split",
   "from": "orders",
   "path": "shipGroups[*].items[*]",
   "levels": [
    "order",
    "group",
    "item"
   ]
  },
  {
   "id": "itemFields",
   "kind": "derive",
   "rules": [
    {
     "set": "unitCount",
     "value": {
      "fn": "units",
      "parse": "STRICT_INT",
      "nullAs": 1,
      "args": [
       {
        "copy": "item.quantity"
       }
      ]
     }
    },
    {
     "set": "shopifyOrderId",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "order.externalId"
       }
      ]
     }
    },
    {
     "set": "shopifyLineId",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "item.externalId"
       }
      ]
     }
    },
    {
     "set": "lineGroup",
     "value": {
      "fn": "join",
      "sep": "|",
      "args": [
       "~unkeyed",
       {
        "fn": "text",
        "args": [
         {
          "copy": "item.orderItemSeqId"
         }
        ]
       }
      ]
     }
    },
    {
     "set": "lineGroup",
     "when": [
      {
       "field": "item.externalId",
       "op": "NOT_BLANK"
      },
      {
       "field": "order.externalId",
       "op": "NOT_BLANK"
      }
     ],
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "item.externalId"
       }
      ]
     }
    },
    {
     "set": "omsOrderId",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "order.orderId"
       }
      ]
     }
    },
    {
     "set": "omsOrderName",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "order.orderName"
       }
      ]
     }
    },
    {
     "set": "orderItemSeqId",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "item.orderItemSeqId"
       }
      ]
     }
    },
    {
     "set": "productId",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "item.productId"
       }
      ]
     }
    },
    {
     "set": "statusId",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "item.statusId"
       }
      ]
     }
    },
    {
     "set": "unitState",
     "value": {
      "map": {
       "ITEM_CREATED": "OPEN",
       "ITEM_APPROVED": "OPEN",
       "ITEM_COMPLETED": "COMPLETED",
       "ITEM_CANCELLED": "CANCELLED"
      },
      "from": "statusId",
      "default": "OTHER"
     }
    },
    {
     "set": "netsuiteOrderId",
     "value": {
      "literal": "NONE"
     }
    },
    {
     "set": "omsOrderStatusId",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "order.statusId"
       }
      ]
     }
    },
    {
     "set": "omsOrderDate",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "order.orderDate"
       }
      ]
     }
    },
    {
     "set": "orderGrandTotal",
     "value": {
      "fn": "decimalPlain",
      "args": [
       {
        "copy": "order.grandTotal"
       }
      ]
     }
    },
    {
     "set": "facilityId",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "group.facilityId"
       }
      ]
     }
    },
    {
     "set": "salesChannelEnumId",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "order.salesChannelEnumId"
       }
      ]
     }
    },
    {
     "set": "sku",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "item.sku"
       }
      ]
     }
    },
    {
     "set": "facilityName",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "group.facilityName"
       }
      ]
     }
    },
    {
     "set": "shipmentMethodTypeId",
     "value": {
      "fn": "text",
      "args": [
       {
        "copy": "group.shipmentMethodTypeId"
       }
      ]
     }
    },
    {
     "set": "customerName",
     "value": {
      "fn": "join",
      "sep": " ",
      "args": [
       {
        "fn": "text",
        "args": [
         {
          "copy": "order.billToCustomer.firstName"
         }
        ]
       },
       {
        "fn": "text",
        "args": [
         {
          "copy": "order.billToCustomer.lastName"
         }
        ]
       }
      ]
     }
    }
   ]
  },
  {
   "id": "unkeyedItems",
   "kind": "count",
   "name": "keptNullShopifyIdCount",
   "when": [
    {
     "any": [
      {
       "field": "item.externalId",
       "op": "BLANK"
      },
      {
       "field": "order.externalId",
       "op": "BLANK"
      }
     ]
    }
   ]
  },
  {
   "id": "nonUnitItems",
   "kind": "count",
   "name": "nonUnitQuantityCount",
   "when": [
    {
     "field": "unitCount",
     "op": "NOT_IN",
     "values": [
      1
     ]
    }
   ]
  },
  {
   "id": "perUnit",
   "kind": "repeat",
   "times": "unitCount",
   "parse": "STRICT_INT",
   "nullAs": 1,
   "index": "unitIndex"
  },
  {
   "id": "unitOrdinal",
   "kind": "number",
   "field": "unitOrdinal",
   "partitionBy": [
    "omsOrderId",
    "lineGroup"
   ],
   "orderBy": [
    {
     "path": "orderItemSeqId",
     "as": "TEXT"
    },
    "unitIndex"
   ]
  },
  {
   "id": "stateOrdinal",
   "kind": "number",
   "field": "stateOrdinal",
   "partitionBy": [
    "omsOrderId",
    "lineGroup",
    "unitState"
   ],
   "orderBy": [
    "unitOrdinal"
   ]
  },
  {
   "id": "exclusions",
   "kind": "filter",
   "overlay": "order",
   "fields": [
    "shopifyOrderId",
    "shopifyLineId",
    "unitOrdinal",
    "omsOrderId",
    "omsOrderName",
    "orderItemSeqId",
    "productId",
    "statusId",
    "unitState",
    "stateOrdinal",
    "omsOrderStatusId",
    "facilityId",
    "orderId",
    "orderName",
    "externalId",
    "orderTypeId",
    "orderDate"
   ]
  }
 ],
 "record": {
  "fields": [
   "shopifyOrderId",
   "shopifyLineId",
   "unitOrdinal",
   "omsOrderId",
   "omsOrderName",
   "orderItemSeqId",
   "productId",
   "statusId",
   "unitState",
   "stateOrdinal",
   "netsuiteOrderId",
   "omsOrderStatusId",
   "omsOrderDate",
   "orderGrandTotal",
   "facilityId",
   "salesChannelEnumId"
  ],
  "optionalFields": [
   "sku",
   "facilityName",
   "shipmentMethodTypeId",
   "customerName"
  ]
 }
}

{
 "connection": {
  "urlTemplate": "{baseUrl}/rest/s1/graphql",
  "auth": {
   "kindField": "authType",
   "defaultKind": "NONE",
   "headersJsonField": "headersJson",
   "kinds": {
    "NONE": {
     "method": "NONE"
    },
    "BASIC": {
     "method": "BASIC",
     "userField": "username",
     "passwordField": "password"
    },
    "BEARER": {
     "method": "BEARER",
     "tokenFields": [
      "apiToken",
      "password"
     ]
    },
    "API_KEY": {
     "method": "HEADER",
     "header": "api_key",
     "tokenFields": [
      "apiToken",
      "password"
     ]
    }
   }
  },
  "timeoutSeconds": 120
 },
 "limits": {
  "maxCostPerCall": 1000,
  "maxInFlight": 6,
  "errorCodeAt": "errors[*].extensions.code",
  "throttledCodes": [
   "THROTTLED"
  ],
  "maxThrottleWaitSeconds": 300,
  "costRefusedCodes": [
   "COST_EXCEEDED"
  ],
  "retryStatuses": [
   429,
   502,
   503,
   504
  ],
  "maxAttempts": 3,
  "retryBackoffMillis": 2000,
  "costBucket": {
   "at": "extensions.cost.throttleStatus",
   "available": "currentlyAvailable",
   "maximum": "maximumAvailable",
   "restoreRate": "restoreRate"
  }
 },
 "batchRecords": 1000,
 "metadata": {
  "requiredOrderTypeId": "SALES_ORDER"
 },
 "steps": [
  {
   "id": "orders",
   "kind": "query",
   "document": "query OmsOrderGrain($q: String, $first: Int, $after: String) {\n  orders(query: $q, sortKey: ORDER_DATE, reverse: false, first: $first, after: $after) {\n    edges { node {\n      orderId orderName externalId statusId orderTypeId orderDate grandTotal {{scalars}}\n      {{payments}}\n      {{nested}}\n    } }\n    pageInfo { hasNextPage endCursor }\n  }\n}",
   "selections": [
    {
     "at": "scalars",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "statusFlowId"
       ]
      }
     ],
     "text": "statusFlowId",
     "cost": 1.5
    },
    {
     "at": "scalars",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "currencyUomId"
       ]
      }
     ],
     "text": "currencyUomId",
     "cost": 1.5
    },
    {
     "at": "scalars",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "productStoreId"
       ]
      }
     ],
     "text": "productStoreId",
     "cost": 1.5
    },
    {
     "at": "scalars",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "salesChannelEnumId"
       ]
      }
     ],
     "text": "salesChannelEnumId",
     "cost": 1.5
    },
    {
     "at": "scalars",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "orderItemCount"
       ]
      }
     ],
     "text": "orderItemCount",
     "cost": 1.5
    },
    {
     "at": "scalars",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "lastUpdatedTxStamp"
       ]
      }
     ],
     "text": "lastUpdatedTxStamp",
     "cost": 1.5
    },
    {
     "at": "payments",
     "when": [
      {
       "field": "wanted[*]",
       "op": "NOT_IN",
       "values": [
        "paymentRefNums",
        "paymentPreferences"
       ]
      }
     ],
     "text": "paymentPreferences(first: 2) { paymentMethodTypeId statusId maxAmount }",
     "cost": 8,
     "set": {
      "paymentSlots": 2,
      "paymentReadsMethods": "Y",
      "paymentReadsRefNums": "N"
     }
    },
    {
     "at": "payments",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "paymentRefNums"
       ]
      },
      {
       "field": "wanted[*]",
       "op": "NOT_IN",
       "values": [
        "paymentMethodTypeIds",
        "paymentPreferences"
       ]
      }
     ],
     "text": "paymentPreferences(first: 5) { manualRefNum }",
     "cost": 10,
     "set": {
      "paymentSlots": 5,
      "paymentReadsMethods": "N",
      "paymentReadsRefNums": "Y"
     }
    },
    {
     "at": "payments",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "paymentRefNums"
       ]
      },
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "paymentMethodTypeIds",
        "paymentPreferences"
       ]
      }
     ],
     "text": "paymentPreferences(first: 5) { paymentMethodTypeId statusId maxAmount manualRefNum }",
     "cost": 25,
     "set": {
      "paymentSlots": 5,
      "paymentReadsMethods": "Y",
      "paymentReadsRefNums": "Y"
     }
    },
    {
     "at": "payments",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "paymentPreferences"
       ]
      },
      {
       "field": "wanted[*]",
       "op": "NOT_IN",
       "values": [
        "paymentRefNums"
       ]
      }
     ],
     "text": "paymentPreferences(first: 5) { paymentMethodTypeId statusId maxAmount }",
     "cost": 20,
     "set": {
      "paymentSlots": 5,
      "paymentReadsMethods": "Y",
      "paymentReadsRefNums": "N"
     }
    },
    {
     "at": "nested",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "identifications"
       ]
      }
     ],
     "text": "identifications(first: 5) { orderIdentificationTypeId idValue }",
     "cost": 18
    },
    {
     "at": "nested",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "shipGroups"
       ]
      }
     ],
     "text": "shipGroups(first: 3) { edges { node { shipGroupSeqId facilityId shipmentMethodTypeId } } }",
     "cost": 12.5
    },
    {
     "at": "nested",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "billToCustomer"
       ]
      }
     ],
     "text": "billToCustomer { firstName lastName }",
     "cost": 2.2
    },
    {
     "at": "nested",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "notes"
       ]
      }
     ],
     "text": "notes(first: 5) { note { noteInfo } }",
     "cost": 25
    },
    {
     "at": "nested",
     "when": [
      {
       "field": "wanted[*]",
       "op": "IN",
       "values": [
        "statuses"
       ]
      }
     ],
     "text": "statuses(first: 12) { statusId statusDatetime orderItemSeqId }",
     "cost": 50
    }
   ],
   "connectionAt": "orders",
   "recordsAt": "edges[*].node",
   "hasNextAt": "pageInfo.hasNextPage",
   "cursorAt": "pageInfo.endCursor",
   "bind": {
    "window": {
     "variables": {
      "q": "orderDate:>={from} orderDate:<{thru} orderTypeId:SALES_ORDER"
     },
     "field": "orderDate",
     "sliceHours": 24,
     "instantFormat": "ISO_INSTANT",
     "parallel": 4
    },
    "ids": {
     "variables": {
      "q": "{keyField}:{ids} orderTypeId:SALES_ORDER"
     },
     "from": "LOOKUP_KEYS",
     "chunk": 100,
     "parallel": 4,
     "defaultKeyField": "orderId",
     "keyFields": {
      "orderId": "orderId",
      "omsOrderId": "orderId",
      "externalId": "externalId"
     },
     "idPattern": "[A-Za-z0-9_\\-]{1,40}",
     "separator": ","
    }
   },
   "paging": {
    "firstVariable": "first",
    "afterVariable": "after",
    "pageSize": {
     "budget": 850,
     "costPerRecord": 8,
     "max": 100
    },
    "maxPages": 20000
   },
   "reservation": 1000
  },
  {
   "id": "assocs",
   "kind": "query",
   "document": "query OmsExchangeAssocs($q: String, $first: Int, $after: String) {\n  orderItemAssocs(query: $q, first: $first, after: $after) {\n    edges { node { orderId orderItemSeqId toOrderId toOrderItemSeqId orderItemAssocTypeId } }\n    pageInfo { hasNextPage endCursor }\n  }\n}",
   "connectionAt": "orderItemAssocs",
   "recordsAt": "edges[*].node",
   "hasNextAt": "pageInfo.hasNextPage",
   "cursorAt": "pageInfo.endCursor",
   "bind": {
    "ids": {
     "variables": {
      "q": "orderId:{ids} orderItemAssocTypeId:EXCHANGE"
     },
     "from": "orders.orderId",
     "chunk": 1000,
     "separator": ","
    }
   },
   "paging": {
    "firstVariable": "first",
    "afterVariable": "after",
    "pageSize": 50,
    "maxPages": 20000
   },
   "reservation": 350
  },
  {
   "id": "onlyExchangeAssocs",
   "kind": "drop",
   "name": "ignoredNonExchangeAssocCount",
   "on": "assocs",
   "when": [
    {
     "field": "orderItemAssocTypeId",
     "op": "NOT_IN",
     "values": [
      "EXCHANGE",
      "exchange",
      "Exchange"
     ]
    }
   ]
  },
  {
   "id": "exchangeGraft",
   "kind": "join",
   "into": "orders",
   "from": "assocs",
   "on": [
    {
     "into": "orderId",
     "from": "orderId"
    }
   ],
   "many": true,
   "as": "orderItemAssocs"
  },
  {
   "id": "groupList",
   "kind": "unwrap",
   "of": "orders",
   "field": "shipGroups",
   "path": "edges[*].node"
  },
  {
   "id": "orderFacts",
   "kind": "derive",
   "on": "orders",
   "rules": [
    {
     "set": "orderDate",
     "value": {
      "fn": "epochMillis",
      "args": [
       {
        "copy": "orderDate"
       }
      ]
     }
    },
    {
     "set": "grandTotal",
     "value": {
      "fn": "decimal",
      "args": [
       {
        "copy": "grandTotal"
       }
      ]
     }
    },
    {
     "set": "isCompleted",
     "value": {
      "map": {
       "ORDER_COMPLETED": "Y"
      },
      "from": "statusId",
      "default": "N"
     }
    },
    {
     "set": "paymentCount",
     "value": {
      "fn": "size",
      "args": [
       {
        "copy": "paymentPreferences"
       }
      ]
     }
    }
   ]
  },
  {
   "id": "paymentFacts",
   "kind": "derive",
   "on": "orders",
   "rules": [
    {
     "set": "hasPaymentPreference",
     "value": {
      "literal": "Y"
     }
    },
    {
     "set": "hasPaymentPreference",
     "when": [
      {
       "field": "paymentCount",
       "op": "IN",
       "values": [
        0
       ]
      }
     ],
     "value": {
      "literal": "N"
     }
    },
    {
     "set": "paymentPreferenceSlotsFull",
     "value": {
      "fn": "atLeast",
      "args": [
       {
        "copy": "paymentCount"
       },
       {
        "copy": "paymentSlots"
       }
      ]
     }
    },
    {
     "set": "paymentMethodTypeIds",
     "when": [
      {
       "field": "paymentReadsMethods",
       "op": "IN",
       "values": [
        "Y"
       ]
      }
     ],
     "value": {
      "fn": "distinctSorted",
      "sep": ",",
      "args": [
       {
        "copy": "paymentPreferences[*].paymentMethodTypeId"
       }
      ]
     }
    },
    {
     "set": "paymentMethodTypeIds",
     "when": [
      {
       "field": "paymentCount",
       "op": "IN",
       "values": [
        0
       ]
      }
     ],
     "value": {
      "literal": ""
     }
    },
    {
     "set": "paymentRefNums",
     "when": [
      {
       "field": "paymentReadsRefNums",
       "op": "IN",
       "values": [
        "Y"
       ]
      }
     ],
     "value": {
      "fn": "distinctSorted",
      "sep": ",",
      "args": [
       {
        "copy": "paymentPreferences[*].manualRefNum"
       }
      ]
     }
    }
   ]
  },
  {
   "id": "refNumsOnlyWhenComplete",
   "kind": "derive",
   "on": "orders",
   "rules": [
    {
     "set": "paymentRefNums",
     "when": [
      {
       "field": "paymentReadsRefNums",
       "op": "IN",
       "values": [
        "Y"
       ]
      },
      {
       "field": "paymentPreferenceSlotsFull",
       "op": "IN",
       "values": [
        true
       ]
      }
     ],
     "value": {
      "literal": null
     }
    }
   ]
  },
  {
   "id": "exchangeOrders",
   "kind": "drop",
   "name": "excludedExchangeOrderCount",
   "on": "orders",
   "when": [
    {
     "field": "orderItemAssocs[*].orderItemAssocTypeId",
     "op": "IN",
     "values": [
      "EXCHANGE",
      "exchange",
      "Exchange"
     ]
    }
   ],
   "sidecar": {
    "suffix": "exchange-manifest",
    "max": 500,
    "fields": {
     "omsOrderId": {
      "fn": "text",
      "args": [
       {
        "copy": "orderId"
       }
      ]
     },
     "externalId": {
      "fn": "text",
      "args": [
       {
        "copy": "externalId"
       }
      ]
     },
     "orderName": {
      "fn": "text",
      "args": [
       {
        "copy": "orderName"
       }
      ]
     },
     "toOrderId": {
      "fn": "text",
      "args": [
       {
        "fn": "first",
        "args": [
         {
          "copy": "orderItemAssocs[*].toOrderId"
         }
        ]
       }
      ]
     },
     "grandTotal": {
      "copy": "grandTotal"
     },
     "orderDate": {
      "copy": "orderDate"
     },
     "statusId": {
      "fn": "text",
      "args": [
       {
        "copy": "statusId"
       }
      ]
     }
    }
   }
  },
  {
   "id": "rules",
   "kind": "filter",
   "fields": [
    "orderId",
    "orderName",
    "externalId",
    "statusId",
    "statusFlowId",
    "orderTypeId",
    "orderDate",
    "grandTotal",
    "currencyUomId",
    "productStoreId",
    "salesChannelEnumId",
    "orderItemCount",
    "lastUpdatedTxStamp",
    "hasPaymentPreference",
    "paymentMethodTypeIds",
    "paymentPreferenceSlotsFull",
    "isCompleted",
    "paymentRefNums",
    "paymentPreferences",
    "identifications",
    "shipGroups",
    "billToCustomer",
    "notes",
    "statuses"
   ]
  }
 ],
 "record": {
  "fields": [
   "orderId",
   "orderName",
   "externalId",
   "statusId",
   "orderTypeId",
   "orderDate",
   "grandTotal",
   "hasPaymentPreference",
   "paymentPreferenceSlotsFull",
   "isCompleted"
  ],
  "optionalFields": [
   "statusFlowId",
   "currencyUomId",
   "productStoreId",
   "salesChannelEnumId",
   "orderItemCount",
   "lastUpdatedTxStamp",
   "paymentMethodTypeIds",
   "paymentRefNums",
   "paymentPreferences",
   "identifications",
   "shipGroups",
   "billToCustomer",
   "notes",
   "statuses"
  ],
  "keepRecordFields": true,
  "keepWith": {
   "paymentPreferences": [
    "paymentPreferenceSlotsFull"
   ]
  }
 }
}

{
 "connection": {
  "urlTemplate": "{baseUrl}/rest/s1/graphql",
  "auth": {
   "kindField": "authType",
   "defaultKind": "NONE",
   "headersJsonField": "headersJson",
   "kinds": {
    "NONE": {
     "method": "NONE"
    },
    "BASIC": {
     "method": "BASIC",
     "userField": "username",
     "passwordField": "password"
    },
    "BEARER": {
     "method": "BEARER",
     "tokenFields": [
      "apiToken",
      "password"
     ]
    },
    "API_KEY": {
     "method": "HEADER",
     "header": "api_key",
     "tokenFields": [
      "apiToken",
      "password"
     ]
    }
   }
  },
  "timeoutSeconds": 120
 },
 "limits": {
  "maxCostPerCall": 1000,
  "maxInFlight": 6,
  "errorCodeAt": "errors[*].extensions.code",
  "throttledCodes": [
   "THROTTLED"
  ],
  "maxThrottleWaitSeconds": 300,
  "costRefusedCodes": [
   "COST_EXCEEDED"
  ],
  "retryStatuses": [
   429,
   502,
   503,
   504
  ],
  "maxAttempts": 3,
  "retryBackoffMillis": 2000,
  "costBucket": {
   "at": "extensions.cost.throttleStatus",
   "available": "currentlyAvailable",
   "maximum": "maximumAvailable",
   "restoreRate": "restoreRate"
  },
  "maxRecordsInMemory": 1000000
 },
 "wholeSet": true,
 "metadata": {
  "windowIgnored": true
 },
 "steps": [
  {
   "id": "products",
   "kind": "query",
   "document": "query OmsProductsSweep($q: String, $first: Int, $after: String) {\n  products(query: $q, first: $first, after: $after) {\n    edges { node { productId internalName productTypeId isVirtual isVariant createdDate salesDiscontinuationDate } }\n    pageInfo { hasNextPage endCursor }\n  }\n}",
   "connectionAt": "products",
   "recordsAt": "edges[*].node",
   "hasNextAt": "pageInfo.hasNextPage",
   "cursorAt": "pageInfo.endCursor",
   "bind": {
    "all": {
     "variables": {}
    }
   },
   "paging": {
    "firstVariable": "first",
    "afterVariable": "after",
    "pageSize": 100,
    "maxPages": 20000
   },
   "reservation": 100
  },
  {
   "id": "netsuiteIds",
   "kind": "query",
   "document": "query OmsNetsuiteIdsSweep($q: String, $first: Int, $after: String) {\n  goodIdentifications(query: $q, first: $first, after: $after) {\n    edges { node { productId idValue thruDate } }\n    pageInfo { hasNextPage endCursor }\n  }\n}",
   "connectionAt": "goodIdentifications",
   "recordsAt": "edges[*].node",
   "hasNextAt": "pageInfo.hasNextPage",
   "cursorAt": "pageInfo.endCursor",
   "bind": {
    "all": {
     "variables": {
      "q": "goodIdentificationTypeId:NETSUITE_PRODUCT_ID"
     }
    }
   },
   "paging": {
    "firstVariable": "first",
    "afterVariable": "after",
    "pageSize": 100,
    "maxPages": 20000
   },
   "reservation": 100
  },
  {
   "id": "netsuiteId",
   "kind": "join",
   "into": "products",
   "from": "netsuiteIds",
   "on": [
    {
     "into": "productId",
     "from": "productId"
    }
   ],
   "copy": {
    "netsuiteProductId": "idValue"
   },
   "fromWhen": [
    {
     "field": "thruDate",
     "op": "BLANK"
    },
    {
     "field": "idValue",
     "op": "NOT_BLANK"
    }
   ],
   "last": true
  },
  {
   "id": "whyNotSellable",
   "kind": "derive",
   "rules": [
    {
     "set": "notSellableReason",
     "when": [
      {
       "field": "productTypeId",
       "op": "NOT_IN",
       "values": [
        "FINISHED_GOOD",
        "MARKETING_PKG_PICK"
       ]
      }
     ],
     "value": {
      "copy": "productTypeId"
     }
    },
    {
     "set": "notSellableReason",
     "when": [
      {
       "field": "isVirtual",
       "op": "IN",
       "values": [
        "Y"
       ]
      }
     ],
     "value": {
      "literal": "virtual"
     }
    },
    {
     "set": "notSellableReason",
     "when": [
      {
       "field": "salesDiscontinuationDate",
       "op": "NOT_BLANK"
      }
     ],
     "value": {
      "literal": "discontinued"
     }
    }
   ]
  },
  {
   "id": "sellableFacts",
   "kind": "derive",
   "rules": [
    {
     "set": "sellable",
     "value": {
      "literal": "Y"
     }
    },
    {
     "set": "sellable",
     "when": [
      {
       "field": "notSellableReason",
       "op": "NOT_BLANK"
      }
     ],
     "value": {
      "literal": "N"
     }
    },
    {
     "set": "sellableOrder",
     "value": {
      "map": {
       "Y": 0
      },
      "from": "sellable",
      "default": 1
     }
    }
   ]
  },
  {
   "id": "productsRead",
   "kind": "count",
   "name": "productsRead"
  },
  {
   "id": "rankAmongSellable",
   "kind": "number",
   "field": "nsRank",
   "partitionBy": [
    "sellable",
    "netsuiteProductId"
   ],
   "orderBy": [
    {
     "path": "productId",
     "as": "TEXT"
    }
   ],
   "sizeField": "nsGroupSize",
   "collect": {
    "field": "productId",
    "as": "nsGroup"
   }
  },
  {
   "id": "rankAmongAll",
   "kind": "number",
   "field": "nsAllRank",
   "partitionBy": [
    "netsuiteProductId"
   ],
   "orderBy": [
    "sellableOrder",
    {
     "path": "productId",
     "as": "TEXT"
    }
   ]
  },
  {
   "id": "onlyNetsuiteItemsNoSellableHolds",
   "kind": "drop",
   "name": "notSellableLeftOut",
   "when": {
    "any": [
     {
      "all": [
       {
        "field": "sellable",
        "op": "IN",
        "values": [
         "N"
        ]
       },
       {
        "field": "netsuiteProductId",
        "op": "BLANK"
       }
      ]
     },
     {
      "all": [
       {
        "field": "sellable",
        "op": "IN",
        "values": [
         "N"
        ]
       },
       {
        "field": "nsAllRank",
        "op": "NOT_IN",
        "values": [
         1
        ]
       }
      ]
     }
    ]
   }
  },
  {
   "id": "keys",
   "kind": "derive",
   "rules": [
    {
     "set": "duplicateNetsuiteId",
     "value": {
      "literal": false
     }
    },
    {
     "set": "duplicateNetsuiteId",
     "when": [
      {
       "field": "sellable",
       "op": "IN",
       "values": [
        "Y"
       ]
      },
      {
       "field": "netsuiteProductId",
       "op": "NOT_BLANK"
      }
     ],
     "value": {
      "fn": "atLeast",
      "args": [
       {
        "copy": "nsGroupSize"
       },
       2
      ]
     }
    },
    {
     "set": "sharedWith",
     "when": [
      {
       "field": "sellable",
       "op": "IN",
       "values": [
        "Y"
       ]
      },
      {
       "field": "netsuiteProductId",
       "op": "NOT_BLANK"
      }
     ],
     "value": {
      "fn": "join",
      "sep": ", ",
      "args": [
       {
        "fn": "without",
        "args": [
         {
          "copy": "nsGroup"
         },
         {
          "copy": "productId"
         }
        ]
       }
      ]
     }
    },
    {
     "set": "nsKey",
     "when": [
      {
       "field": "sellable",
       "op": "IN",
       "values": [
        "Y"
       ]
      },
      {
       "field": "netsuiteProductId",
       "op": "BLANK"
      }
     ],
     "value": {
      "fn": "join",
      "sep": ":",
      "args": [
       "HOTWAX-ONLY",
       {
        "copy": "productId"
       }
      ]
     }
    },
    {
     "set": "nsKey",
     "when": [
      {
       "field": "sellable",
       "op": "IN",
       "values": [
        "Y"
       ]
      },
      {
       "field": "netsuiteProductId",
       "op": "NOT_BLANK"
      },
      {
       "field": "nsRank",
       "op": "IN",
       "values": [
        1
       ]
      }
     ],
     "value": {
      "copy": "netsuiteProductId"
     }
    },
    {
     "set": "nsKey",
     "when": [
      {
       "field": "sellable",
       "op": "IN",
       "values": [
        "Y"
       ]
      },
      {
       "field": "netsuiteProductId",
       "op": "NOT_BLANK"
      },
      {
       "field": "nsRank",
       "op": "NOT_IN",
       "values": [
        1
       ]
      }
     ],
     "value": {
      "fn": "join",
      "sep": ":",
      "args": [
       "DUPLICATE",
       {
        "copy": "netsuiteProductId"
       },
       {
        "copy": "productId"
       }
      ]
     }
    },
    {
     "set": "nsKey",
     "when": [
      {
       "field": "sellable",
       "op": "IN",
       "values": [
        "N"
       ]
      }
     ],
     "value": {
      "copy": "netsuiteProductId"
     }
    },
    {
     "set": "netsuiteIdState",
     "when": [
      {
       "field": "sellable",
       "op": "IN",
       "values": [
        "Y"
       ]
      },
      {
       "field": "netsuiteProductId",
       "op": "BLANK"
      }
     ],
     "value": {
      "literal": "NONE"
     }
    },
    {
     "set": "netsuiteIdState",
     "when": [
      {
       "field": "sellable",
       "op": "IN",
       "values": [
        "Y"
       ]
      },
      {
       "field": "netsuiteProductId",
       "op": "NOT_BLANK"
      },
      {
       "field": "nsRank",
       "op": "IN",
       "values": [
        1
       ]
      }
     ],
     "value": {
      "literal": "OWN"
     }
    },
    {
     "set": "netsuiteIdState",
     "when": [
      {
       "field": "sellable",
       "op": "IN",
       "values": [
        "Y"
       ]
      },
      {
       "field": "netsuiteProductId",
       "op": "NOT_BLANK"
      },
      {
       "field": "nsRank",
       "op": "NOT_IN",
       "values": [
        1
       ]
      }
     ],
     "value": {
      "literal": "SHARED"
     }
    },
    {
     "set": "netsuiteIdState",
     "when": [
      {
       "field": "sellable",
       "op": "IN",
       "values": [
        "N"
       ]
      }
     ],
     "value": {
      "literal": "OWN"
     }
    }
   ]
  },
  {
   "id": "sellableCount",
   "kind": "count",
   "name": "sellable",
   "when": [
    {
     "field": "sellable",
     "op": "IN",
     "values": [
      "Y"
     ]
    }
   ]
  },
  {
   "id": "withoutNetsuiteId",
   "kind": "count",
   "name": "withoutNetsuiteId",
   "when": [
    {
     "field": "sellable",
     "op": "IN",
     "values": [
      "Y"
     ]
    },
    {
     "field": "netsuiteProductId",
     "op": "BLANK"
    }
   ]
  },
  {
   "id": "severalProducts",
   "kind": "count",
   "name": "netsuiteIdsOnSeveralProducts",
   "when": [
    {
     "field": "sellable",
     "op": "IN",
     "values": [
      "Y"
     ]
    },
    {
     "field": "netsuiteProductId",
     "op": "NOT_BLANK"
    },
    {
     "field": "nsRank",
     "op": "IN",
     "values": [
      2
     ]
    }
   ]
  },
  {
   "id": "notSellableKept",
   "kind": "count",
   "name": "notSellableWithNetsuiteId",
   "when": [
    {
     "field": "sellable",
     "op": "IN",
     "values": [
      "N"
     ]
    }
   ]
  },
  {
   "id": "rules",
   "kind": "filter",
   "fields": [
    "productId",
    "internalName",
    "productTypeId",
    "createdDate",
    "netsuiteProductId",
    "nsKey",
    "duplicateNetsuiteId",
    "sharedWith",
    "netsuiteIdState",
    "sellable",
    "notSellableReason"
   ]
  }
 ],
 "record": {
  "fields": [
   "productId",
   "internalName",
   "productTypeId",
   "createdDate",
   "netsuiteProductId",
   "nsKey",
   "duplicateNetsuiteId",
   "sharedWith",
   "netsuiteIdState",
   "sellable"
  ],
  "optionalFields": [
   "notSellableReason"
  ]
 }
}

